```js
export function packSlots(items, slotSize) {
	const order = [...items].sort((x, y) => y.size - x.size || (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
	const slots = [];
	const used = [];
	for (const item of order) {
		if (item.size > slotSize) {
			throw new RangeError(`item "${item.id}" (size ${item.size}) does not fit in slotSize ${slotSize}`);
		}
		let placed = false;
		for (let i = 0; i < slots.length; i++) {
			if (used[i] + item.size <= slotSize) {
				slots[i].push(item.id);
				used[i] += item.size;
				placed = true;
				break;
			}
		}
		if (!placed) {
			slots.push([item.id]);
			used.push(item.size);
		}
	}
	return slots;
}
